import {
  HTMLAttributes,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'preact/compat';
import { Container, SlotProps } from '@adobe-commerce/elsie/lib';
import { Wishlist as WishlistComponent } from '@/wishlist/components';
import { ProductItemActionsContext } from '@/wishlist/components/ProductItem';
import { events, WishlistActionPayload } from '@adobe-commerce/event-bus';
import {
  Item,
  PageInfo,
  Product,
  Wishlist as WishlistModel,
} from '@/wishlist/data/models';
import { state } from '@/wishlist/lib/state';
import { WishlistAlert } from '@/wishlist/containers/WishlistAlert';
import { ImageProps } from '@adobe-commerce/elsie/components';
import { getWishlistById } from '@/wishlist/api/getWishlistById';
import { DEFAULT_PAGE_SIZE } from '@/wishlist/api/constants';

export interface WishlistProps extends HTMLAttributes<HTMLDivElement> {
  routeEmptyWishlistCTA?: () => string;
  routeToWishlist?: string;
  // When provided, the container renders this specific wishlist instead of the
  // active/default one, and does not touch `state.wishlistId`. Pair it with
  // `scope` so this instance's events stay isolated from the active list. When
  // omitted, behavior is unchanged (renders the active list).
  wishlistId?: string;
  scope?: string;
  moveProdToCart: (
    products: { sku: string; quantity: number }[]
  ) => Promise<any>;
  routeProdDetailPage: (product: Product) => string;
  getProductData?: (sku: string) => Promise<Product | null>;
  getRefinedProduct?: (
    sku: string,
    optionUIDs: string[],
    anchorOptions?: string[],
    raw?: boolean
  ) => Promise<Product | null>;
  slots?: {
    image?: SlotProps<{
      defaultImageProps: ImageProps;
      item: Item;
    }>;
    actions?: SlotProps<ProductItemActionsContext>;
  };
}

export const Wishlist: Container<WishlistProps> = ({
  routeEmptyWishlistCTA,
  routeToWishlist,
  wishlistId,
  scope,
  moveProdToCart,
  routeProdDetailPage,
  getProductData,
  getRefinedProduct,
  slots,
  ...props
}: WishlistProps) => {
  const pageSize = state.pageSize ?? DEFAULT_PAGE_SIZE;
  const [wishlistData, setWishlistData] = useState<WishlistModel | null>(null);
  const [isLoggedIn, setIsLoggedIn] = useState(state.authenticated);
  const [isLoading, setIsLoading] = useState(state.isLoading ?? false);
  const [activePage, setActivePage] = useState(1);
  const [isLoadingPage, setIsLoadingPage] = useState(false);
  // Ref mirrors isLoadingPage so event-handler closures (handleWishlistData)
  // can read the current value synchronously without a stale capture.
  const isLoadingPageRef = useRef(false);

  const setPageLoading = (loading: boolean) => {
    isLoadingPageRef.current = loading;
    setIsLoadingPage(loading);
  };

  const handleAuthentication = (authenticated: boolean) =>
    setIsLoggedIn(authenticated);

  // Fetch a page and broadcast it on this instance's channel. Specific-list
  // mode emits on `scope` (so only this container reacts); active-list mode
  // emits unscoped as before. Either way the data reaches this container via
  // its own `wishlist/data` subscription below.
  const reloadPage = useCallback(
    (page: number) =>
      wishlistId
        ? getWishlistById(wishlistId, pageSize, page, { scope })
        : getWishlistById(state.wishlistId as string, pageSize, page),
    [wishlistId, scope, pageSize]
  );

  const handlePageChange = useCallback(
    async (page: number) => {
      if (isLoadingPageRef.current) return;
      // Active-list mode requires a known active id; specific-list mode always
      // knows its target via `wishlistId`.
      if (!wishlistId && !state.wishlistId) return;
      setPageLoading(true);
      try {
        await reloadPage(page);
      } finally {
        setPageLoading(false);
      }
    },
    [wishlistId, reloadPage]
  );

  const [wishlistAlert, setWishlistAlert] = useState<Element | null>(null);
  const handleWishlistAlert = useCallback(
    (payload: WishlistActionPayload) => {
      const { action, item } = payload;
      setWishlistAlert(
        <WishlistAlert
          action={action}
          item={item}
          routeToWishlist={routeToWishlist}
        />
      );

      // Authenticated specific-list mode: the server remove is non-emitting, so
      // refresh the shown page here (page-aware). Guest specific lists already
      // arrive updated via the mutation's scoped `wishlist/data` emit, so no
      // re-read is needed for them.
      if (wishlistId && state.authenticated) {
        reloadPage(activePage);
      }
    },
    [routeToWishlist, wishlistId, activePage, reloadPage]
  );

  const handleWishlistData = useCallback(
    (payload: WishlistModel | null) => {
      const wishlist = payload as WishlistModel;
      const currentPage = wishlist?.page_info?.currentPage ?? null;
      const totalPages = wishlist?.page_info?.totalPages ?? 0;
      const hasItems = (wishlist?.items?.length ?? 0) > 0;

      // Navigate before committing empty state to avoid flashing the
      // empty-wishlist panel when the last item on a non-first page is deleted.
      if (
        !hasItems &&
        totalPages >= 1 &&
        currentPage != null &&
        currentPage > 1 &&
        (wishlistId || state.wishlistId) &&
        !isLoadingPageRef.current
      ) {
        const targetPage = Math.min(currentPage - 1, totalPages);
        setPageLoading(true);
        reloadPage(targetPage).finally(() => {
          setPageLoading(false);
        });
        return;
      }

      setWishlistData(wishlist);
      setIsLoading(false);
    },
    [wishlistId, reloadPage]
  );

  useEffect(() => {
    if (!wishlistData) return;

    const currentPage = wishlistData.page_info?.currentPage ?? null;

    if (currentPage != null) {
      setActivePage(currentPage);
      // Only the active-list mode owns the global pagination state.
      if (!wishlistId) {
        state.currentPage = currentPage;
      }
    }

    setPageLoading(false);

    const receivedPageSize = wishlistData.page_info?.pageSize;
    const needsRefetch =
      pageSize !== DEFAULT_PAGE_SIZE &&
      receivedPageSize != null &&
      receivedPageSize !== pageSize &&
      !isLoadingPageRef.current;

    if (needsRefetch && (wishlistId || state.wishlistId)) {
      setPageLoading(true);
      reloadPage(1).finally(() => setPageLoading(false));
    }
  }, [wishlistData, pageSize, wishlistId, reloadPage]);

  useEffect(() => {
    const authEvent = events.on('authenticated', handleAuthentication);
    // Both data and alert events are scoped to this instance. For the active
    // list `scope` is undefined (unscoped, unchanged); for a specific list it
    // isolates this container from the active list and any other instance.
    const updateEvent = events.on('wishlist/alert', handleWishlistAlert, {
      scope,
    });
    const dataEvent = events.on('wishlist/data', handleWishlistData, {
      eager: true,
      scope,
    });
    return () => {
      authEvent?.off();
      dataEvent?.off();
      updateEvent?.off();
    };
  }, [handleWishlistAlert, handleWishlistData, scope]);

  // Specific-list mode: load the target list once (and whenever it changes).
  // The load emits on our scope and the subscription above renders it.
  useEffect(() => {
    if (!wishlistId) return;
    setIsLoading(true);
    Promise.resolve(reloadPage(1))
      .catch(() => undefined)
      .finally(() => setIsLoading(false));
  }, [wishlistId, reloadPage]);

  const pageInfo: PageInfo | undefined =
    pageSize !== DEFAULT_PAGE_SIZE ? wishlistData?.page_info : undefined;

  return (
    <WishlistComponent
      {...props}
      wishlistData={wishlistData}
      wishlistAlert={wishlistAlert}
      routeEmptyWishlistCTA={routeEmptyWishlistCTA}
      wishlistId={wishlistId}
      scope={scope}
      moveProdToCart={moveProdToCart}
      getProductData={getProductData}
      getRefinedProduct={getRefinedProduct}
      isLoggedIn={isLoggedIn}
      isLoading={isLoading}
      routeProdDetailPage={routeProdDetailPage}
      pageInfo={pageInfo}
      activePage={activePage}
      onPageChange={handlePageChange}
      isLoadingPage={isLoadingPage}
      slots={slots}
    />
  );
};
