import {
  HTMLAttributes,
  useEffect,
  useState,
  useCallback,
} from 'preact/compat';
import { Container, SlotProps } from '@adobe-commerce/elsie/lib';
import { ProductItem, ProductItemActionsContext } from '@/wishlist/components';
import { Item, Product } from '@/wishlist/data/models';
import { removeProductsFromWishlist } from '@/wishlist/api';
import { events } from '@adobe-commerce/event-bus';
import { ImageNodeRenderProps } from '@adobe-commerce/elsie/components';
import { JSX } from 'preact';
import { redirect } from '@/wishlist/lib/navigation';

export interface WishlistItemProps extends HTMLAttributes<HTMLDivElement> {
  item: Item;
  // When set, item actions target this specific list (non-emitting). The
  // `wishlist/alert` event still fires so the host container can refresh. When
  // omitted, actions target the active list via the global event (unchanged).
  wishlistId?: string;
  // Event scope for the `wishlist/alert` this item emits, so only the matching
  // host container reacts. Omit for the active/default list (unscoped).
  scope?: string;
  getProductData?: (sku: string) => Promise<Product | null>;
  getRefinedProduct?: (
    sku: string,
    optionUIDs: string[],
    anchorOptions?: string[],
    raw?: boolean
  ) => Promise<Product | null>;
  moveProdToCart: (
    products: {
      sku: string;
      quantity: number;
      optionsUIDs?: [];
      enteredOptions?: [];
    }[]
  ) => Promise<any>;
  routeProdDetailPage: (product: Product) => string;
  imageNode?: (props: {
    defaultImageProps: ImageNodeRenderProps;
  }) => JSX.Element;
  slots?: {
    actions?: SlotProps<ProductItemActionsContext>;
  };
}

export const WishlistItem: Container<WishlistItemProps> = ({
  item,
  wishlistId,
  scope,
  getProductData,
  getRefinedProduct,
  moveProdToCart,
  routeProdDetailPage,
  imageNode,
  slots,
}: WishlistItemProps) => {
  const [productData, setProductData] = useState<Product | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function fetchProductData() {
      try {
        let data: Product | null;
        if (getRefinedProduct && item?.selectedOptions?.length > 0) {
          data = await getRefinedProduct(
            item.product.sku,
            item.selectedOptions.map((option: { uid: any }) => option.uid)
          );
        } else {
          data = getProductData
            ? await getProductData(item?.product.sku)
            : item?.product;
        }
        if (!cancelled) setProductData(data);
      } catch (err) {
        if (!cancelled) {
          console.error('Failed to fetch product data:', err);
        }
      }
    }

    fetchProductData();

    return () => {
      cancelled = true;
    };
  }, [item, getProductData, getRefinedProduct]);

  /**
   * Removes product from wishlist
   */
  const removeProductFromWishlist = useCallback(
    async (showAlert: boolean = true): Promise<boolean> => {
      try {
        await removeProductsFromWishlist([item], wishlistId, { scope });
        console.log(`Product ${productData?.sku} removed from wishlist!`);
        if (showAlert) {
          events.emit(
            'wishlist/alert',
            {
              action: 'remove',
              item: { ...item, product: productData },
            },
            { scope }
          );
        }
        return true;
      } catch (error) {
        console.error(
          `Product ${productData.sku} could not be removed from wishlist`,
          error
        );
        return false;
      }
    },
    [item, productData, wishlistId, scope]
  );

  /**
   * Moves product to cart
   */
  const moveProductToCart = useCallback(async (): Promise<boolean> => {
    try {
      await moveProdToCart([
        {
          sku: productData.sku,
          quantity: 1,
          optionsUIDs: item.selectedOptions?.map(
            (option: { uid: any }) => option.uid
          ),
          enteredOptions: item.enteredOptions,
        },
      ]);
      console.log(`Product ${productData.sku} successfully moved to cart 🛒`);
      // Remove from the list first, then emit the alert. In specific-list mode
      // the alert triggers a non-emitting reload, so the removal must complete
      // before it, otherwise the reloaded list still shows the moved item.
      const removed = await removeProductFromWishlist(false);
      events.emit(
        'wishlist/alert',
        {
          action: 'move',
          item: { ...item, product: productData },
        },
        { scope }
      );
      return removed;
    } catch (error) {
      console.error('Could not move product to cart: ', error);
      if (
        error.toString().includes('You need to choose options for your item.')
      ) {
        redirect(routeProdDetailPage(productData));
      }
      return false;
    }
  }, [
    productData,
    item,
    scope,
    moveProdToCart,
    routeProdDetailPage,
    removeProductFromWishlist,
  ]);

  if (!productData || !item) return null;

  return (
    <ProductItem
      item={{ ...item, product: productData }}
      onCartActionButtonClick={moveProductToCart}
      onTrashButtonClick={removeProductFromWishlist}
      routeProdDetailPage={routeProdDetailPage}
      imageNode={imageNode}
      slots={slots}
    />
  );
};
