import { FunctionComponent, VNode } from 'preact';
import { HTMLAttributes, useState, useEffect, useMemo } from 'preact/compat';
import {
  VComponent,
  classes,
  Slot,
  SlotProps,
} from '@adobe-commerce/elsie/lib';
import { WishlistSkeleton } from '@/wishlist/components/Wishlist/WishlistSkeleton';
import '@/wishlist/components/Wishlist/Wishlist.css';
import {
  PageInfo,
  Product,
  Wishlist as WishlistModel,
  Item,
} from '@/wishlist/data/models';
import { WishlistItem } from '@/wishlist/containers';
import { ProductItemActionsContext } from '@/wishlist/components/ProductItem';
import { Fragment } from 'react';
import { EmptyWishlist, Login } from '@/wishlist/components';
import { useText } from '@adobe-commerce/elsie/i18n';
import {
  ImageProps,
  LiveRegion,
  Pagination,
} from '@adobe-commerce/elsie/components';

export interface WishlistProps extends HTMLAttributes<HTMLDivElement> {
  className?: string;
  wishlistData: WishlistModel;
  wishlistAlert: VNode | null;
  isLoggedIn: boolean;
  isLoading: boolean;
  moveProdToCart: (
    products: { sku: string; quantity: number }[],
  ) => Promise<any>;
  getProductData?: (sku: string) => Promise<Product | null>;
  getRefinedProduct?: (
    sku: string,
    optionUIDs: string[],
    anchorOptions?: string[],
    raw?: boolean,
  ) => Promise<Product | null>;
  routeEmptyWishlistCTA?: () => string;
  onLoginClick?: () => void;
  routeProdDetailPage: (product: Product) => string;
  wishlistId?: string;
  scope?: string;
  pageInfo?: PageInfo;
  activePage?: number;
  onPageChange?: (page: number) => void;
  isLoadingPage?: boolean;
  slots?: {
    image?: SlotProps<{
      defaultImageProps: ImageProps;
      item: Item;
    }>;
    actions?: SlotProps<ProductItemActionsContext>;
  };
}

export const Wishlist: FunctionComponent<WishlistProps> = ({
  className,
  wishlistData,
  wishlistAlert,
  isLoggedIn,
  isLoading,
  moveProdToCart,
  getProductData,
  getRefinedProduct,
  routeEmptyWishlistCTA,
  onLoginClick,
  routeProdDetailPage,
  wishlistId,
  scope,
  pageInfo,
  activePage = 1,
  onPageChange,
  isLoadingPage = false,
  slots,
  ...props
}) => {
  const [alert, setAlert] = useState<VNode | null>(wishlistAlert);

  const dictionary = useText({
    wishlistHeading: 'Wishlist.Wishlist.heading',
    wishlistLoadingHeading: 'Wishlist.Wishlist.loading',
    alertMoveMessage: 'Wishlist.Alert.moveToCart.message',
    alertRemoveMessage: 'Wishlist.Alert.removeProduct.message',
  });

  const alertMessage = (() => {
    if (!alert) return '';
    const props = alert.props as Record<string, any>;
    const action = props?.action;
    if (action === 'move' || action === 'remove') {
      const productName = props?.item?.product?.name || '';
      const message =
        action === 'move'
          ? dictionary.alertMoveMessage
          : dictionary.alertRemoveMessage;
      return message.replace('{product}', productName);
    }
    return '';
  })();


  const products = useMemo(() => {
    return wishlistData?.items?.length > 0
      ? wishlistData.items.map((item: Item) => (
          <WishlistItem
            key={item.id}
            item={item}
            wishlistId={wishlistId}
            scope={scope}
            getProductData={getProductData}
            getRefinedProduct={getRefinedProduct}
            moveProdToCart={moveProdToCart}
            routeProdDetailPage={routeProdDetailPage}
            imageNode={
              slots?.image
                ? ({ defaultImageProps }) => (
                    <Slot
                      name="image"
                      slot={slots.image}
                      context={{
                        defaultImageProps,
                        item,
                      }}
                    />
                  )
                : undefined
            }
            slots={{ actions: slots?.actions }}
          />
        ))
      : null;
  }, [
    wishlistData,
    wishlistId,
    scope,
    moveProdToCart,
    getProductData,
    getRefinedProduct,
    routeProdDetailPage,
    slots?.image,
    slots?.actions,
  ]);

  useEffect(() => {
    if (wishlistAlert) {
      setAlert(wishlistAlert);

      const timer = setTimeout(() => {
        setAlert(null);
      }, 5000);

      return () => clearTimeout(timer);
    }
  }, [wishlistAlert]);

  const renderAlert = useMemo(
    () =>
      alert ? (
        <VComponent node={alert} className="wishlist-wishlist__alert" />
      ) : null,
    [alert],
  );

  const renderLoader = () => {
    return (
      <>
        <div
          className="wishlist-wishlist__heading"
          data-testid="wishlist-heading-wrapper"
        >
          <h1
            className="wishlist-wishlist__heading-text"
            data-testid="loader-wishlist-heading"
          >
            {dictionary.wishlistLoadingHeading}
          </h1>
        </div>
        <WishlistSkeleton />
      </>
    );
  };

  const renderWishlist = () => {
    return products ? (
      <>
        {renderHeading}
        {isLoadingPage ? (
          <WishlistSkeleton />
        ) : (
          <div className="wishlist-wishlist__content">{products}</div>
        )}
        {pageInfo && (pageInfo.totalPages ?? 0) > 1 && (
          <div className="wishlist-wishlist__pagination">
            <Pagination
              currentPage={activePage}
              totalPages={pageInfo.totalPages}
              onChange={onPageChange}
            />
          </div>
        )}
      </>
    ) : (
      <div
        className={classes([
          'wishlist-wishlist__content',
          'wishlist-wishlist__content--empty',
        ])}
      >
        <div>
          <EmptyWishlist
            data-testid="empty-wishlist"
            ctaLinkURL={routeEmptyWishlistCTA?.()}
          />
          {!isLoggedIn && <Login onLoginClick={onLoginClick} />}
        </div>
      </div>
    );
  };

  const renderHeading = useMemo(() => {
    if (!products) return null;

    return (
      <div
        className="wishlist-wishlist__heading"
        data-testid="wishlist-heading-wrapper"
      >
        <h1
          className="wishlist-wishlist__heading-text"
          data-testid="default-wishlist-heading"
        >
          {dictionary.wishlistHeading
            ?.split(' {count}')
            .map((title: string, index: number) => (
              <Fragment key={wishlistData?.id?.toString() + index}>
                {title}
                {index === 0 && (
                  <span
                    className="wishlist-wishlist__heading-count"
                    data-testid="wishlist-heading-count"
                  >
                    {`${wishlistData?.items_count} products`}
                  </span>
                )}
              </Fragment>
            ))}
        </h1>
      </div>
    );
  }, [dictionary, products, wishlistData]);

  return (
    <div {...props} className={classes(['wishlist-wishlist', className])}>
      <LiveRegion message={alertMessage} />
      <div className="wishlist-wishlist__alert-region">{renderAlert}</div>
      <LiveRegion
        message={isLoadingPage ? dictionary.wishlistLoadingHeading : ''}
      />
      {isLoading ? renderLoader() : renderWishlist()}
    </div>
  );
};
